public sealed record State(bool Busy = false, string? Error = null);
public abstract record Event;
public sealed record Submit(string User) : Event;
public sealed record Failed(string Reason) : Event;
public sealed class LoginBloc {
    private readonly BehaviorSubject<State> _state = new(new State());
    public IObservable<State> State => _state.AsObservable();
    public void Dispatch(Event e) => _state.OnNext(e switch {
        Submit => new State(Busy: true),
        Failed f => new State(Error: f.Reason),
        _ => _state.Value });   // dispose subscriptions with the component
}

