var events = Channel.CreateUnbounded<Event>();
var states = Channel.CreateBounded<State>(new BoundedChannelOptions(1) {
    FullMode = BoundedChannelFullMode.DropOldest });
_ = Task.Run(async () => {
    var state = new State();
    await foreach (var e in events.Reader.ReadAllAsync()) {
        state = Reduce(state, e);
        states.Writer.TryWrite(state);      // keep only the latest state
    }
});
